#!/usr/bin/python
import os
import sys
import time

base = os.path.dirname(os.path.abspath(__file__))
results_path = os.path.join(base, "results.tsv")

try:
    job_count = int(sys.argv[1])
except (IndexError, ValueError):
    sys.stderr.write("usage: %s JOB_COUNT\n" % sys.argv[0])
    sys.exit(2)

if job_count < 0:
    sys.stderr.write("JOB_COUNT must be non-negative\n")
    sys.exit(2)

children = {}
for number in range(job_count):
    pid = os.fork()
    if pid == 0:
        time.sleep(0.1)
        os._exit((number % 2) * 3)
    children[pid] = number

results = open(results_path, "a")
try:
    while children:
        pid, status = os.wait()
        number = children.pop(pid)
        if os.WIFEXITED(status):
            exit_status = os.WEXITSTATUS(status)
        elif os.WIFSIGNALED(status):
            exit_status = 128 + os.WTERMSIG(status)
        else:
            continue
        results.write("current,%d,%d\n" % (number, exit_status))
        results.flush()
finally:
    results.close()
ANTRIEB_SUPERVISOR_EOF
